  1	/**
  2	 * Audit-log writer and reader. Subscribes to the whole event bus and records one row per domain event.
  3	 *
  4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, toCsv
  5	 */
  6	import { toCsv } from "@/lib/csv";
  7	import { subscribe } from "@/lib/event-bus";
  8	import { isEnabled } from "@/lib/feature-flags";
  9	import { assertCan } from "@/lib/permissions";
 10	import { assertOrgScope } from "@/lib/tenant";
 11	import * as activityRepo from "@/server/repositories/activity-repository";
 12	import * as orgRepo from "@/server/repositories/organization-repository";
 13	import { toIsoTimestamp } from "@/types/common";
 14	import { activityResource } from "./_support";
 15	import type { ActivityFilterInput, ExportActivityInput } from "@/schemas/activity";
 16	import type {
 17	  ActivityAction,
 18	  ActivityEvent,
 19	  ActivityGroup,
 20	  ActivitySubjectKind,
 21	} from "@/types/activity";
 22	import type { OrgId, Page, ProjectId, UserId } from "@/types/common";
 23	import type { Unsubscribe } from "@/types/event";
 24	import type { Actor } from "@/types/member";
 25	
 26	export type ActivityRecordInput = {
 27	  actorId: UserId | null;
 28	  subjectKind: ActivitySubjectKind;
 29	  subjectId: string;
 30	  projectId: ProjectId | null;
 31	  summary: string;
 32	  metadata?: Readonly<Record<string, string | number | boolean | null>>;
 33	};
 34	
 35	/** Columns of the audit-log CSV export, in the order the file lists them. */
 36	const EXPORT_COLUMNS = [
 37	  "occurredAt",
 38	  "action",
 39	  "actorId",
 40	  "subjectKind",
 41	  "subjectId",
 42	  "summary",
 43	] as const;
 44	
 45	/**
 46	 * Appends one audit row. Deliberately takes no `Actor`: the writer is usually
 47	 * an event handler running outside a request, and the row's `actorId` comes
 48	 * from the event payload rather than from an authenticated principal.
 49	 */
 50	export async function record(
 51	  orgId: OrgId,
 52	  action: ActivityAction,
 53	  input: ActivityRecordInput,
 54	): Promise<ActivityEvent> {
 55	  return activityRepo.insertActivity({
 56	    orgId,
 57	    action,
 58	    actorId: input.actorId,
 59	    subjectKind: input.subjectKind,
 60	    subjectId: input.subjectId,
 61	    projectId: input.projectId,
 62	    summary: input.summary,
 63	    metadata: input.metadata ?? {},
 64	    occurredAt: toIsoTimestamp(new Date()),
 65	  });
 66	}
 67	
 68	export async function listActivity(
 69	  actor: Actor,
 70	  input: ActivityFilterInput,
 71	): Promise<Page<ActivityEvent>> {
 72	  assertOrgScope(actor, input.orgId);
 73	  assertCan(actor, "activity:read", activityResource(input.orgId));
 74	  return activityRepo.listActivity(input);
 75	}
 76	
 77	/** Groups a feed page by calendar day, newest day first. */
 78	export function groupByDay(
 79	  events: readonly ActivityEvent[],
 80	): readonly ActivityGroup[] {
 81	  const byDay = new Map<string, ActivityEvent[]>();
 82	
 83	  for (const event of events) {
 84	    const day = event.occurredAt.slice(0, 10);
 85	    const bucket = byDay.get(day) ?? [];
 86	    bucket.push(event);
 87	    byDay.set(day, bucket);
 88	  }
 89	
 90	  return [...byDay.entries()]
 91	    .sort(([a], [b]) => (a < b ? 1 : -1))
 92	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
 93	}
 94	
 95	/**
 96	 * CSV (or JSON) export of the audit log. Gated twice: on `activity:export`
 97	 * for the role, and on the `csv_export` flag for the plan.
 98	 */
 99	export async function exportActivity(
100	  actor: Actor,
101	  input: ExportActivityInput,
102	): Promise<string> {
103	  assertOrgScope(actor, input.orgId);
104	  assertCan(actor, "activity:export", activityResource(input.orgId));
105	
106	  const org = await orgRepo.findOrgById(input.orgId);
107	  const flagEnabled = isEnabled("csv_export", {
108	    orgId: input.orgId,
109	    userId: actor.userId,
110	    plan: org?.plan ?? "free",
111	    role: actor.role,
112	    overrides: org?.settings.enabledFlagOverrides,
113	  });
114	
115	  if (input.format === "csv" && !flagEnabled) {
116	    throw new Error("CSV export is not included in this plan");
117	  }
118	
119	  const page = await activityRepo.listActivity({
120	    orgId: input.orgId,
121	    since: input.since,
122	    until: input.until,
123	    limit: 100,
124	    cursor: null,
125	  });
126	
127	  if (input.format === "json") {
128	    return JSON.stringify(page.items, null, 2);
129	  }
130	
131	  return toCsv(
132	    page.items.map((event) => ({
133	      occurredAt: event.occurredAt,
134	      action: event.action,
135	      actorId: event.actorId,
136	      subjectKind: event.subjectKind,
137	      subjectId: event.subjectId,
138	      summary: event.summary,
139	    })),
140	    [...EXPORT_COLUMNS],
141	  );
142	}
143	
144	/**
145	 * Attaches one handler per audited event type. Called once from
146	 * `event-registry`; the returned function detaches all of them, which is what
147	 * the test suite uses to keep the bus clean between cases.
148	 */
149	export function registerActivityListeners(): Unsubscribe {
150	  const offs: Unsubscribe[] = [
151	    subscribe("project.created", (payload) =>
152	      record(payload.orgId, "project.created", {
153	        actorId: payload.actorId,
154	        subjectKind: "project",
155	        subjectId: payload.projectId,
156	        projectId: payload.projectId,
157	        summary: `Created project ${payload.name}`,
158	      }).then(() => undefined),
159	    ),
160	    subscribe("project.archived", (payload) =>
161	      record(payload.orgId, "project.archived", {
162	        actorId: payload.actorId,
163	        subjectKind: "project",
164	        subjectId: payload.projectId,
165	        projectId: payload.projectId,
166	        summary: `Archived project with ${payload.issuesArchived} issues`,
167	      }).then(() => undefined),
168	    ),
169	    subscribe("issue.created", (payload) =>
170	      record(payload.orgId, "issue.created", {
171	        actorId: payload.actorId,
172	        subjectKind: "issue",
173	        subjectId: payload.issueId,
174	        projectId: payload.projectId,
175	        summary: `Created issue "${payload.title}"`,
176	        metadata: { priority: payload.priority },
177	      }).then(() => undefined),
178	    ),
179	    subscribe("issue.status_changed", (payload) =>
180	      record(payload.orgId, "issue.status_changed", {
181	        actorId: payload.actorId,
182	        subjectKind: "issue",
183	        subjectId: payload.issueId,
184	        projectId: payload.projectId,
185	        summary: `Status ${payload.from} → ${payload.to}`,
186	        metadata: { from: payload.from, to: payload.to },
187	      }).then(() => undefined),
188	    ),
189	    subscribe("issue.assigned", (payload) =>
190	      record(payload.orgId, "issue.assigned", {
191	        actorId: payload.actorId,
192	        subjectKind: "issue",
193	        subjectId: payload.issueId,
194	        projectId: payload.projectId,
195	        summary: `Assigned to ${payload.assigneeId}`,
196	      }).then(() => undefined),
197	    ),
198	    subscribe("comment.created", (payload) =>
199	      record(payload.orgId, "comment.created", {
200	        actorId: payload.actorId,
201	        subjectKind: "comment",
202	        subjectId: payload.commentId,
203	        projectId: null,
204	        summary: `Commented on issue ${payload.issueId}`,
205	      }).then(() => undefined),
206	    ),
207	    subscribe("member.invited", (payload) =>
208	      record(payload.orgId, "member.invited", {
209	        actorId: payload.actorId,
210	        subjectKind: "member",
211	        subjectId: payload.email,
212	        projectId: null,
213	        summary: `Invited ${payload.email} as ${payload.role}`,
214	      }).then(() => undefined),
215	    ),
216	    subscribe("member.role_changed", (payload) =>
217	      record(payload.orgId, "member.role_changed", {
218	        actorId: payload.actorId,
219	        subjectKind: "member",
220	        subjectId: payload.memberId,
221	        projectId: null,
222	        summary: `Role ${payload.from} → ${payload.to}`,
223	      }).then(() => undefined),
224	    ),
225	    subscribe("billing.plan_changed", (payload) =>
226	      record(payload.orgId, "billing.plan_changed", {
227	        actorId: payload.actorId,
228	        subjectKind: "subscription",
229	        subjectId: payload.orgId,
230	        projectId: null,
231	        summary: `Plan ${payload.from} → ${payload.to}`,
232	      }).then(() => undefined),
233	    ),
234	  ];
235	
236	  return () => {
237	    for (const off of offs) off();
238	  };
239	}
  1	/**
  2	 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
  3	 *
  4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
  5	 */
  6	import { subscribe } from "@/lib/event-bus";
  7	import { isEnabled } from "@/lib/feature-flags";
  8	import { assertCan } from "@/lib/permissions";
  9	import { consumeRateLimit } from "@/lib/rate-limit";
 10	import { assertOrgScope } from "@/lib/tenant";
 11	import * as commentRepo from "@/server/repositories/comment-repository";
 12	import * as issueRepo from "@/server/repositories/issue-repository";
 13	import * as orgRepo from "@/server/repositories/organization-repository";
 14	import * as projectRepo from "@/server/repositories/project-repository";
 15	import * as searchRepo from "@/server/repositories/search-repository";
 16	import { orgResource } from "./_support";
 17	import type { SearchQueryInput } from "@/schemas/search";
 18	import type { SearchSubjectKind } from "@/server/repositories/search-repository";
 19	import type { Comment } from "@/types/comment";
 20	import type { OrgId, Page } from "@/types/common";
 21	import type { Unsubscribe } from "@/types/event";
 22	import type { Issue } from "@/types/issue";
 23	import type { Actor } from "@/types/member";
 24	import type { Project } from "@/types/project";
 25	
 26	export type SearchHit = {
 27	  kind: SearchSubjectKind;
 28	  id: string;
 29	  title: string;
 30	  snippet: string;
 31	  href: string;
 32	};
 33	
 34	/** Characters of surrounding context kept on either side of a match. */
 35	const SNIPPET_RADIUS = 60;
 36	
 37	/** Token bucket protecting the index from query bursts. */
 38	const SEARCH_QUERY_BUCKET = "search:query";
 39	
 40	/**
 41	 * Runs a query against the denormalised index. Field-scoped syntax
 42	 * (`status:done`) is an `advanced_search` feature, so a query containing a
 43	 * colon is rejected for plans that do not include it rather than silently
 44	 * being treated as literal text.
 45	 */
 46	export async function search(
 47	  actor: Actor,
 48	  input: SearchQueryInput,
 49	): Promise<Page<SearchHit>> {
 50	  assertOrgScope(actor, input.orgId);
 51	  assertCan(actor, "issue:read", orgResource(input.orgId));
 52	
 53	  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
 54	  if (!verdict.allowed) {
 55	    throw new Error(
 56	      `Search rate limit reached; try again after ${verdict.resetAt}`,
 57	    );
 58	  }
 59	
 60	  const org = await orgRepo.findOrgById(input.orgId);
 61	  const advanced = isEnabled("advanced_search", {
 62	    orgId: input.orgId,
 63	    userId: actor.userId,
 64	    plan: org?.plan ?? "free",
 65	    role: actor.role,
 66	    overrides: org?.settings.enabledFlagOverrides,
 67	  });
 68	
 69	  if (input.q.includes(":") && !advanced) {
 70	    throw new Error("Field-scoped search is not included in this plan");
 71	  }
 72	
 73	  const page = await searchRepo.searchDocuments(input);
 74	
 75	  return {
 76	    items: page.items.map((row) => ({
 77	      kind: row.subjectKind,
 78	      id: row.subjectId,
 79	      title: row.content.split("\n")[0] ?? row.subjectId,
 80	      snippet: snippetAround(row.content, input.q),
 81	      href: hrefFor(row.subjectKind, row.subjectId),
 82	    })),
 83	    nextCursor: page.nextCursor,
 84	    total: page.total,
 85	  };
 86	}
 87	
 88	export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
 89	  await searchRepo.upsertSearchDocument(
 90	    orgId,
 91	    "issue",
 92	    issue.id,
 93	    [issue.title, issue.description ?? ""].join("\n"),
 94	    issue.projectId,
 95	  );
 96	}
 97	
 98	export async function indexComment(
 99	  orgId: OrgId,
100	  comment: Comment,
101	): Promise<void> {
102	  await searchRepo.upsertSearchDocument(
103	    orgId,
104	    "comment",
105	    comment.id,
106	    comment.body,
107	    null,
108	  );
109	}
110	
111	export async function indexProject(
112	  orgId: OrgId,
113	  project: Project,
114	): Promise<void> {
115	  await searchRepo.upsertSearchDocument(
116	    orgId,
117	    "project",
118	    project.id,
119	    [project.name, project.description ?? ""].join("\n"),
120	    project.id,
121	  );
122	}
123	
124	export async function removeFromIndex(
125	  orgId: OrgId,
126	  subjectKind: SearchSubjectKind,
127	  subjectId: string,
128	): Promise<void> {
129	  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
130	}
131	
132	/**
133	 * Keeps the index in step with writes. Every handler re-reads the row rather
134	 * than trusting the event payload, so a partially-applied write can never be
135	 * indexed as if it had succeeded.
136	 */
137	export function registerSearchListeners(): Unsubscribe {
138	  const offs: Unsubscribe[] = [
139	    subscribe("issue.created", async (payload) => {
140	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
141	      if (issue) await indexIssue(payload.orgId, issue);
142	    }),
143	    subscribe("issue.updated", async (payload) => {
144	      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
145	      if (issue) await indexIssue(payload.orgId, issue);
146	    }),
147	    subscribe("issue.archived", async (payload) => {
148	      await removeFromIndex(payload.orgId, "issue", payload.issueId);
149	    }),
150	    subscribe("comment.created", async (payload) => {
151	      const comment = await commentRepo.findCommentById(
152	        payload.orgId,
153	        payload.commentId,
154	      );
155	      if (comment) await indexComment(payload.orgId, comment);
156	    }),
157	    subscribe("comment.deleted", async (payload) => {
158	      await removeFromIndex(payload.orgId, "comment", payload.commentId);
159	    }),
160	    subscribe("project.created", async (payload) => {
161	      const project = await projectRepo.findProjectById(
162	        payload.orgId,
163	        payload.projectId,
164	      );
165	      if (project) await indexProject(payload.orgId, project);
166	    }),
167	    subscribe("project.archived", async (payload) => {
168	      await removeFromIndex(payload.orgId, "project", payload.projectId);
169	    }),
170	    subscribe("search.reindex_requested", async (payload) => {
171	      if (payload.subjectKind !== "issue") return;
172	      const issue = await issueRepo.findIssueById(
173	        payload.orgId,
174	        payload.subjectId as Issue["id"],
175	      );
176	      if (issue) await indexIssue(payload.orgId, issue);
177	    }),
178	  ];
179	
180	  return () => {
181	    for (const off of offs) off();
182	  };
183	}
184	
185	function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
186	  switch (kind) {
187	    case "issue":
188	      return `/issues/${subjectId}`;
189	    case "comment":
190	      return `/comments/${subjectId}`;
191	    case "project":
192	      return `/projects/${subjectId}`;
193	  }
194	}
195	
196	function snippetAround(content: string, query: string): string {
197	  const at = content.toLowerCase().indexOf(query.toLowerCase());
198	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
199	
200	  const start = Math.max(0, at - SNIPPET_RADIUS);
201	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
202	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
203	    end < content.length ? "…" : ""
204	  }`;
205	}
  1	/**
  2	 * Recomputes the usage counters that every `LimitCheck` compares against.
  3	 *
  4	 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
  5	 */
  6	import { getPlanLimits } from "@/config/plan-limits";
  7	import { emit, subscribe } from "@/lib/event-bus";
  8	import { assertOrgScope } from "@/lib/tenant";
  9	import * as orgRepo from "@/server/repositories/organization-repository";
 10	import * as usageRepo from "@/server/repositories/usage-repository";
 11	import { toIsoTimestamp } from "@/types/common";
 12	import type { OrgId } from "@/types/common";
 13	import type { Unsubscribe } from "@/types/event";
 14	import type { Actor } from "@/types/member";
 15	import type { OrganizationUsage } from "@/types/organization";
 16	
 17	/** Fraction of a quota at which the "approaching limit" event fires. */
 18	const WARN_THRESHOLD = 0.9;
 19	
 20	export async function getUsage(
 21	  actor: Actor,
 22	  orgId: OrgId,
 23	): Promise<OrganizationUsage> {
 24	  assertOrgScope(actor, orgId);
 25	  return usageRepo.getUsage(orgId);
 26	}
 27	
 28	/**
 29	 * Full recount from the source tables. Called by the rollup job and by every
 30	 * event that could have moved a counter — after recounting, the seat and
 31	 * project totals are checked against the plan so a breach surfaces as an
 32	 * event rather than waiting for the next write to be rejected.
 33	 */
 34	export async function recomputeUsage(
 35	  orgId: OrgId,
 36	): Promise<OrganizationUsage> {
 37	  const usage = await usageRepo.recomputeUsage(orgId);
 38	  const org = await orgRepo.findOrgById(orgId);
 39	  if (!org) return usage;
 40	
 41	  const limits = getPlanLimits(org.plan);
 42	
 43	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
 44	    await emit("billing.limit_exceeded", {
 45	      orgId,
 46	      actorId: null,
 47	      occurredAt: toIsoTimestamp(new Date()),
 48	      resource: "seats",
 49	      limit: limits.seats,
 50	      used: usage.seatsUsed,
 51	    });
 52	  }
 53	
 54	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
 55	    await emit("billing.limit_exceeded", {
 56	      orgId,
 57	      actorId: null,
 58	      occurredAt: toIsoTimestamp(new Date()),
 59	      resource: "projects",
 60	      limit: limits.projects,
 61	      used: usage.projectsUsed,
 62	    });
 63	  }
 64	
 65	  return usage;
 66	}
 67	
 68	/**
 69	 * Every event that changes a counted resource nudges the cache. The deltas are
 70	 * cheap; the periodic rollup is what corrects any drift they accumulate.
 71	 */
 72	export function registerUsageListeners(): Unsubscribe {
 73	  const offs: Unsubscribe[] = [
 74	    subscribe("issue.created", async (payload) => {
 75	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
 76	    }),
 77	    subscribe("issue.archived", async (payload) => {
 78	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
 79	    }),
 80	    subscribe("project.created", async (payload) => {
 81	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
 82	    }),
 83	    subscribe("project.archived", async (payload) => {
 84	      await usageRepo.incrementUsage(payload.orgId, {
 85	        projectsUsed: -1,
 86	        issuesUsed: -payload.issuesArchived,
 87	      });
 88	    }),
 89	    subscribe("member.joined", async (payload) => {
 90	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
 91	    }),
 92	    subscribe("member.removed", async (payload) => {
 93	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
 94	    }),
 95	  ];
 96	
 97	  return () => {
 98	    for (const off of offs) off();
 99	  };
100	}

