  1	"use server";
  2	
  3	/**
  4	 * Creates an issue after the per-project quota check.
  5	 *
  6	 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
  7	 * here — the plan of the owning organization decides `issuesPerProject`.
  8	 *
  9	 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
 10	 * getActor, toActionResult
 11	 */
 12	
 13	import { withAction } from "@/actions/_lib/with-action";
 14	import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
 15	import { getPlanLimits } from "@/config/plan-limits";
 16	import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
 17	import { can } from "@/lib/permissions";
 18	import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
 19	import { createIssue, listIssues } from "@/server/services/issue-service";
 20	import { getOrganizationSummary } from "@/server/services/organization-service";
 21	import type { ActionResult } from "@/types/api";
 22	import type { Issue } from "@/types/issue";
 23	import type { Actor } from "@/types/member";
 24	
 25	const run = withAction<typeof createIssueSchema, Issue>(
 26	  createIssueSchema,
 27	  async (raw, actor) => {
 28	    const input = raw as CreateIssueInput;
 29	
 30	    const allowed = can(actor, "issue:create", {
 31	      kind: "issue",
 32	      orgId: input.orgId,
 33	      projectId: input.projectId,
 34	      issueId: "" as Issue["id"],
 35	      authorId: actor.userId,
 36	      assigneeId: input.assigneeId,
 37	    });
 38	    if (!allowed) {
 39	      throw new ForbiddenActionError("issue:create");
 40	    }
 41	
 42	    await assertProjectHasRoom(actor, input);
 43	
 44	    const issue = await createIssue(actor, input);
 45	
 46	    revalidateTagged(
 47	      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
 48	      CACHE_PROFILES.minutes,
 49	    );
 50	    return issue;
 51	  },
 52	  { revalidate: ["issues"], cacheProfile: "minutes" },
 53	);
 54	
 55	/**
 56	 * Counts the issues already living in the project and compares them with the
 57	 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
 58	 * which is why the count deliberately includes them.
 59	 */
 60	async function assertProjectHasRoom(
 61	  actor: Actor,
 62	  input: CreateIssueInput,
 63	): Promise<void> {
 64	  const summary = await getOrganizationSummary(actor, input.orgId);
 65	  const limits = getPlanLimits(summary.organization.plan);
 66	
 67	  const existing = await listIssues(actor, {
 68	    orgId: input.orgId,
 69	    projectId: input.projectId,
 70	    limit: 1,
 71	    includeArchived: true,
 72	  });
 73	
 74	  if (existing.total >= limits.issuesPerProject) {
 75	    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
 76	  }
 77	}
 78	
 79	export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
 80	  return run(raw);
 81	}
  1	/**
  2	 * The `organization_usage` counters read by every plan-limit check.
  3	 */
  4	import { and, count, eq, isNull, sql } from "drizzle-orm";
  5	import {
  6	  attachments,
  7	  getDb,
  8	  issues,
  9	  members,
 10	  organizationUsage,
 11	  projects,
 12	} from "@/server/db";
 13	import { toIsoTimestamp } from "@/types/common";
 14	import { toUsage } from "./_mappers";
 15	import { brandId } from "./_mappers";
 16	import type { OrgId } from "@/types/common";
 17	import type { OrganizationUsage } from "@/types/organization";
 18	
 19	const BYTES_PER_MB = 1024 * 1024;
 20	
 21	/**
 22	 * Reads the cached counters, materialising a zeroed row the first time an org
 23	 * is asked about. A limit check must never fail because the rollup has not run.
 24	 */
 25	export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
 26	  const row = getDb()
 27	    .select()
 28	    .from(organizationUsage)
 29	    .where(eq(organizationUsage.orgId, orgId))
 30	    .get();
 31	
 32	  if (row) return toUsage(row);
 33	
 34	  const created = getDb()
 35	    .insert(organizationUsage)
 36	    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
 37	    .returning()
 38	    .get();
 39	
 40	  return toUsage(created);
 41	}
 42	
 43	/**
 44	 * Recounts every dimension from the source tables and rewrites the cache.
 45	 * Called by the rollup job and after any bulk change that would drift.
 46	 */
 47	export async function recomputeUsage(
 48	  orgId: OrgId,
 49	): Promise<OrganizationUsage> {
 50	  const db = getDb();
 51	
 52	  const seats = db
 53	    .select({ value: count() })
 54	    .from(members)
 55	    .where(
 56	      and(
 57	        eq(members.orgId, orgId),
 58	        eq(members.status, "active"),
 59	        isNull(members.archivedAt),
 60	      ),
 61	    )
 62	    .get();
 63	
 64	  const projectCount = db
 65	    .select({ value: count() })
 66	    .from(projects)
 67	    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
 68	    .get();
 69	
 70	  const issueCount = db
 71	    .select({ value: count() })
 72	    .from(issues)
 73	    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
 74	    .get();
 75	
 76	  const bytes = db
 77	    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
 78	    .from(attachments)
 79	    .where(eq(attachments.orgId, orgId))
 80	    .get();
 81	
 82	  const next = {
 83	    orgId,
 84	    seatsUsed: seats?.value ?? 0,
 85	    projectsUsed: projectCount?.value ?? 0,
 86	    issuesUsed: issueCount?.value ?? 0,
 87	    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
 88	    measuredAt: toIsoTimestamp(new Date()),
 89	  };
 90	
 91	  const row = db
 92	    .insert(organizationUsage)
 93	    .values(next)
 94	    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
 95	    .returning()
 96	    .get();
 97	
 98	  return toUsage(row);
 99	}
100	
101	/**
102	 * Cheap delta applied on the write path so a quota check right after a create
103	 * sees the new number without waiting for the rollup.
104	 */
105	export async function incrementUsage(
106	  orgId: OrgId,
107	  patch: Partial<
108	    Pick<
109	      OrganizationUsage,
110	      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
111	    >
112	  >,
113	): Promise<OrganizationUsage> {
114	  const current = await getUsage(orgId);
115	
116	  const row = getDb()
117	    .update(organizationUsage)
118	    .set({
119	      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
120	      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
121	      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
122	      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
123	      measuredAt: toIsoTimestamp(new Date()),
124	    })
125	    .where(eq(organizationUsage.orgId, orgId))
126	    .returning()
127	    .get();
128	
129	  return toUsage(row);
130	}
131	
132	/** The rollup job's work list: the oldest measurements first. */
133	export async function listOrgIdsForRollup(
134	  limit: number,
135	): Promise<readonly OrgId[]> {
136	  const rows = getDb()
137	    .select({ orgId: organizationUsage.orgId })
138	    .from(organizationUsage)
139	    .orderBy(organizationUsage.measuredAt)
140	    .limit(Math.max(1, limit))
141	    .all();
142	
143	  return rows.map((row) => brandId<OrgId>(row.orgId));
144	}
  1	/**
  2	 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
  3	 *
  4	 * Must call (do not reimplement): shouldFilterArchived
  5	 */
  6	import { eq, isNull } from "drizzle-orm";
  7	import { shouldFilterArchived } from "@/lib/soft-delete";
  8	import type { ArchiveScope, OrgId } from "@/types/common";
  9	import type { SQL } from "drizzle-orm";
 10	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
 11	
 12	const CURSOR_SEPARATOR = "|";
 13	
 14	/**
 15	 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 16	 * sort value alongside the id is what lets `listX` resume from a stable point
 17	 * even when two rows share a timestamp.
 18	 */
 19	export function encodeCursor(id: string, sortValue: string): string {
 20	  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
 21	    "base64url",
 22	  );
 23	}
 24	
 25	export function decodeCursor(
 26	  cursor: string,
 27	): { id: string; sortValue: string } | null {
 28	  let decoded: string;
 29	  try {
 30	    decoded = Buffer.from(cursor, "base64url").toString("utf8");
 31	  } catch {
 32	    return null;
 33	  }
 34	
 35	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
 36	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
 37	
 38	  return {
 39	    sortValue: decoded.slice(0, separatorAt),
 40	    id: decoded.slice(separatorAt + 1),
 41	  };
 42	}
 43	
 44	/**
 45	 * The tenant predicate. Every repository read and write composes this — a
 46	 * query that does not mention `org_id` is a cross-tenant leak waiting to
 47	 * happen, so this is the only sanctioned way to express it.
 48	 */
 49	export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
 50	  return eq(column, orgId);
 51	}
 52	
 53	/**
 54	 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 55	 * for archived rows. The `includeArchived` decision itself lives in
 56	 * `shouldFilterArchived()` so it cannot drift per repository.
 57	 */
 58	export function livePredicate(
 59	  column: SQLiteColumn,
 60	  scope: ArchiveScope,
 61	): SQL | undefined {
 62	  return shouldFilterArchived(scope) ? isNull(column) : undefined;
 63	}

