  6	  UserId,
  7	} from "./common";
  8	
  9	/** The verb recorded in the audit log. Kept deliberately close to the event
 10	 *  bus keys so `ActivityService` can map one to the other mechanically. */
 11	export type ActivityAction =
 12	  | "organization.updated"
 13	  | "project.created"
 14	  | "project.updated"
 15	  | "project.archived"
 16	  | "project.restored"
 17	  | "issue.created"
