 26	  | "member.invited"
 27	  | "member.joined"
 28	  | "member.role_changed"
 29	  | "member.removed"
 30	  | "billing.plan_changed"
 31	  | "flag.toggled";
 32	
 33	export type ActivitySubjectKind =
 34	  | "organization"
 35	  | "project"
 36	  | "issue"
 37	  | "comment"
 38	  | "member"
 39	  | "subscription"
 40	  | "feature_flag";
 41	
 42	export interface ActivityEvent extends TenantScoped {
 43	  readonly id: ActivityId;
 44	  readonly action: ActivityAction;
 45	  readonly actorId: UserId | null;
 46	  readonly subjectKind: ActivitySubjectKind;
 47	  readonly subjectId: string;
 48	  readonly projectId: ProjectId | null;
 49	  readonly summary: string;
 50	  readonly metadata: Readonly<Record<string, string | number | boolean | null>>;
 51	  readonly occurredAt: IsoTimestamp;
 52	}
 53	
 54	/** Filter for the activity feed page and the audit-log CSV export. */
 55	export interface ActivityFilter {
