  2	 * Test double for `@/lib/id` (owner E).
  3	 *
  4	 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
  5	 * failing assertion names the same row on every run. Counter-based rather than
  6	 * random for exactly that reason.
  7	 */
  8	const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
  9	const ULID_LENGTH = 26;
 10	
 11	let counter = 0;
 12	
 13	export function newId(): string {
 14	  counter += 1;
 15	  return encode(counter);
 16	}
 17	
 18	export function isUlid(value: string): boolean {
 19	  return (
 20	    value.length === ULID_LENGTH &&
 21	    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
 22	  );
 23	}
 24	
 25	export function idFactory(seed: number): () => string {
 26	  let local = seed;
 27	  return () => {
 28	    local += 1;
 29	    return encode(local);
 30	  };
 31	}
 32	
 33	/** Test-only: rewinds the counter so each file starts from the same ids. */
 34	export function resetIds(): void {
 35	  counter = 0;
 36	}
 37	
 38	function encode(value: number): string {
 39	  let remaining = value;
 40	  let out = "";
 41	
 42	  while (out.length < ULID_LENGTH) {
 43	    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
 44	    remaining = Math.floor(remaining / 32);
 45	  }
 46	
 47	  return out.slice(-ULID_LENGTH);
 48	}
  1	/**
  2	 * Test doubles for the `src/lib` helpers owned by E.
  3	 *
  4	 * The server layer legitimately depends on them, but they are still stubs at
  5	 * the time this suite runs, so each is replaced with the smallest faithful
  6	 * implementation the assertions need. Swap-in only — no server code is mocked.
  7	 */
  8	import type { UserId } from "@/types/common";
  9	import type { MemberWithUser } from "@/types/member";
 10	import type { IsoTimestamp, OrgId } from "@/types/common";
 11	
 12	/* -------------------------------------------------------------- @/lib/hash */
 13	
 14	export const hashModule = {
 15	  hashPassword: async (password: string): Promise<string> =>
 16	    `scrypt$${password.length}$${simpleHash(password)}`,
 17	  verifyPassword: async (password: string, hash: string): Promise<boolean> =>
 18	    (await hashModule.hashPassword(password)) === hash,
 19	  hashToken: (token: string): string => `sha256$${simpleHash(token)}`,
 20	  randomToken: (bytes = 32): string =>
 21	    `t${simpleHash(String(tokenCounter++))}`.padEnd(bytes, "x"),
 22	};
 23	
 24	let tokenCounter = 1;
 25	
 26	/* -------------------------------------------------------- @/lib/rate-limit */
 27	
 28	/** Verdicts the suite can steer: the default is "always allowed". */
 29	export const rateLimitState = { allowed: true, remaining: 100 };
 30	
 31	export const rateLimitModule = {
 32	  consumeRateLimit: async (
 33	    _orgId: OrgId,
 34	    _bucketKey: string,
 35	    cost = 1,
 36	  ): Promise<{
 37	    allowed: boolean;
 38	    remaining: number;
 39	    resetAt: IsoTimestamp;
 40	  }> => ({
 41	    allowed: rateLimitState.allowed,
 42	    remaining: Math.max(0, rateLimitState.remaining - cost),
 43	    resetAt: new Date(Date.now() + 60_000).toISOString() as IsoTimestamp,
 44	  }),
 45	  getBucketConfig: () => ({ capacity: 100, refillPerMinute: 100 }),
 46	  RATE_LIMIT_BUCKETS: {} as Readonly<
 47	    Record<string, { capacity: number; refillPerMinute: number }>
 48	  >,
 49	};
 50	
 51	/* ---------------------------------------------------------- @/lib/mentions */
 52	
 53	export const mentionsModule = {
 54	  extractMentions: (body: string): readonly string[] =>
 55	    [...body.matchAll(/@([\w.-]+)/g)].map((match) => match[1] ?? ""),
 56	  resolveMentions: (
 57	    body: string,
 58	    members: readonly MemberWithUser[],
 59	  ): readonly UserId[] => {
 60	    const handles = new Set(
 61	      mentionsModule.extractMentions(body).map((handle) => handle.toLowerCase()),
 62	    );
 63	    return members
 64	      .filter(
 65	        (member) =>
 66	          handles.has(member.user.name.toLowerCase()) ||
 67	          handles.has(member.user.email.split("@")[0]?.toLowerCase() ?? ""),
 68	      )
 69	      .map((member) => member.userId);
 70	  },
 71	  highlightMentions: (body: string): string =>
 72	    body.replace(/@([\w.-]+)/g, "<b>@$1</b>"),
 73	};
 74	
 75	/* ------------------------------------------------------------ @/lib/logger */
 76	
 77	export const loggerModule = {
 78	  createLogger: () => ({
 79	    debug: () => undefined,
 80	    info: () => undefined,
 81	    warn: () => undefined,
 82	    error: () => undefined,
 83	  }),
 84	};
 85	
 86	/* --------------------------------------------------------------- @/lib/csv */
 87	
 88	export const csvModule = {
 89	  toCsv: (
 90	    rows: readonly Readonly<
 91	      Record<string, string | number | boolean | null>
 92	    >[],
 93	    columns: readonly string[],
 94	  ): string =>
 95	    [
 96	      columns.join(","),
 97	      ...rows.map((row) =>
 98	        columns.map((column) => csvModule.escapeCsvValue(row[column] ?? null)).join(","),
 99	      ),
100	    ].join("\n"),
101	  escapeCsvValue: (value: string | number | boolean | null): string => {
102	    const text = value === null ? "" : String(value);
103	    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
104	  },
105	  csvResponseHeaders: (filename: string) => ({
106	    "content-type": "text/csv",
107	    "content-disposition": `attachment; filename="${filename}"`,
108	  }),
109	};
110	
111	function simpleHash(value: string): string {
112	  let hash = 2_166_136_261;
113	  for (let i = 0; i < value.length; i += 1) {
114	    hash ^= value.charCodeAt(i);
115	    hash = Math.imul(hash, 16_777_619);
116	  }
117	  return Math.abs(hash).toString(36);
118	}

