     1	/**
     2	 * Presentation helpers for the audit trail.
     3	 *
     4	 * `ActivityEvent.summary` is written by the service layer and is authoritative;
     5	 * these helpers only supply the verb chip and the day grouping the feed and the
     6	 * per-issue panel both render, so the two views never disagree about what a
     7	 * day boundary is.
     8	 */
     9	import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";
    10	
    11	export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
    12	  "organization.updated": "updated the organization",
    13	  "project.created": "created a project",
    14	  "project.updated": "updated a project",
    15	  "project.archived": "archived a project",
    16	  "project.restored": "restored a project",
    17	  "issue.created": "created an issue",
    18	  "issue.updated": "updated an issue",
    19	  "issue.status_changed": "changed status",
    20	  "issue.assigned": "assigned an issue",
    21	  "issue.archived": "archived an issue",
    22	  "issue.restored": "restored an issue",
    23	  "comment.created": "commented",
    24	  "comment.updated": "edited a comment",
    25	  "comment.deleted": "deleted a comment",
    26	  "member.invited": "invited a member",
    27	  "member.joined": "joined the organization",
    28	  "member.role_changed": "changed a role",
    29	  "member.removed": "removed a member",
    30	  "billing.plan_changed": "changed the plan",
    31	  "flag.toggled": "toggled a feature flag",
    32	};
    33	
    34	export function activityLabel(action: ActivityAction): string {
    35	  return ACTIVITY_LABELS[action] ?? action;
    36	}
    37	
    38	/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
    39	export function activityDay(event: ActivityEvent): string {
    40	  return event.occurredAt.slice(0, 10);
    41	}
    42	
    43	/**
    44	 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
    45	 * newest day first and newest event first within a day.
    46	 */
    47	export function groupEventsByDay(
    48	  events: readonly ActivityEvent[],
    49	): readonly ActivityGroup[] {
    50	  const byDay = new Map<string, ActivityEvent[]>();
    51	
    52	  for (const event of events) {
    53	    const day = activityDay(event);
    54	    const bucket = byDay.get(day) ?? [];
    55	    bucket.push(event);
    56	    byDay.set(day, bucket);
    57	  }
    58	
    59	  return [...byDay.entries()]
    60	    .sort(([a], [b]) => b.localeCompare(a))
    61	    .map(([day, bucket]) => ({
    62	      day,
    63	      events: [...bucket].sort((a, b) =>
    64	        b.occurredAt.localeCompare(a.occurredAt),
