 * Note: `next lint` was removed in Next 16 — run `pnpm lint` (`eslint .`).
 */
const config = [
  {
    ignores: [
      ".next/**",
      "node_modules/**",
      "drizzle/**",
      "data/**",
      "next-env.d.ts",
