/**
 * Bulk-import records and the all-or-nothing write behind `IssueService.importIssues`.
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, parseJsonArray } from "./_mappers";
import type { IssueImportRow } from "@/server/db";
import type {
  IsoTimestamp,
  IssueId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

/** A persisted import: which key produced which issues, in file order. */
export interface IssueImportRecord {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly importedBy: UserId;
  readonly issueIds: readonly IssueId[];
  readonly createdAt: IsoTimestamp;
}

/** One row of the file, already resolved against the workspace's members. */
export interface ImportIssueDraft {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Label names, each at most once. */
  readonly labelNames: readonly string[];
}

export interface InsertImportInput {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportIssueDraft[];
  /** Colour given to labels the import has to create. */
  readonly newLabelColor: string;
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toImportRecord(row) : null;
}

/**
 * Writes a whole import in one transaction: claims the key, creates the
 * labels the workspace does not have yet, numbers the issues after the
 * highest number the project has used, inserts them in file order and links
 * their labels. Returns `null`, having written nothing, when the key has
 * already been claimed.
 */
export async function insertImport(
  input: InsertImportInput,
): Promise<IssueImportRecord | null> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const claimed = tx
      .select({ id: issueImports.id })
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (claimed) return null;

    const labelIdByName = new Map<string, string>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, input.orgId))
        .all()
        .map((label) => [label.name, label.id]),
    );

    for (const name of input.rows.flatMap((row) => row.labelNames)) {
      if (labelIdByName.has(name)) continue;
      const id = newId();
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          color: input.newLabelColor,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, id);
    }

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    const firstNumber = (highest?.value ?? 0) + 1;

    const issueIds = input.rows.map((row, index) => {
      const id = newId();
      tx.insert(issues)
        .values({
          id,
          orgId: input.orgId,
          projectId: input.projectId,
          number: firstNumber + index,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (row.labelNames.length > 0) {
        tx.insert(issueLabels)
          .values(
            row.labelNames.map((name) => ({
              orgId: input.orgId,
              issueId: id,
              labelId: labelIdByName.get(name) ?? "",
            })),
          )
          .run();
      }

      return id;
    });

    const record = tx
      .insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        projectId: input.projectId,
        importKey: input.importKey,
        importedBy: input.authorId,
        issueIds: JSON.stringify(issueIds),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return toImportRecord(record);
  });
}

function toImportRecord(row: IssueImportRow): IssueImportRecord {
  return {
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    importKey: row.importKey,
    importedBy: brandId<UserId>(row.importedBy),
    issueIds: parseJsonArray<string>(row.issueIds).map((id) =>
      brandId<IssueId>(id),
    ),
    createdAt: brandStamp(row.createdAt),
  };
}

