 * Batch read that keeps the caller's order, so a list of ids stored in file
 * order comes back in file order. Ids that do not resolve are skipped.
 */
export async function findIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();

  const labels = await listLabelsForIssues(orgId, issueIds);
  const byId = new Map(rows.map((row) => [row.id, row]));

  return issueIds.flatMap((issueId) => {
    const row = byId.get(issueId);
    return row
      ? [toIssue(row, (labels[row.id] ?? []).map((label) => label.id))]
      : [];
  });
}

