/**
 * The plan's per-project issue quota, for a single create and a whole import
 * alike: refuses when `requested` more issues would take the project over it.
 */
async function assertProjectHasRoom(
  project: Project,
  requested: number,
): Promise<void> {
  const org = requireFound(
    await orgRepo.findOrgById(project.orgId),
    "Organization",
    project.orgId,
  );
  const used = await issueRepo.countIssues(project.orgId, project.id);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, requested)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }
}

/** The first import's issues, as they are now, in file order. */
async function replayImport(
  record: IssueImportRecord,
): Promise<IssueImportResult> {
  return {
    importKey: record.importKey,
    projectId: record.projectId,
    issues: await issueRepo.findIssuesByIds(record.orgId, record.issueIds),
    replayed: true,
  };
}

/**
 * Resolves one file row against the workspace. An address that is not a
 * current member's leaves the issue unassigned; a label named twice in the
 * row counts once.
 */
function toImportDraft(
  row: ImportIssueRowInput,
  assignees: ReadonlyMap<string, UserId>,
): ImportIssueDraft {
  const email = row.assigneeEmail?.toLowerCase() ?? null;
  return {
    title: row.title,
    description: row.description ?? null,
    status: row.status ?? "backlog",
    priority: row.priority ?? "none",
    assigneeId: email === null ? null : (assignees.get(email) ?? null),
    dueAt: row.dueAt ?? null,
    labelNames: [...new Set(row.labels ?? [])],
  };
}
'''
