/**
 * Bulk issue import: access, all-or-nothing checks, row mapping, replays and
 * the single `issues.imported` announcement, with the application's event
 * handlers attached the way `instrumentation.ts` attaches them.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { consumeRateLimit, getBucketConfig } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import { getDb, labels, notifications, webhookDeliveries } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];
let keySeq = 0;

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function freshKey(): string {
  keySeq += 1;
  return `upload-${String(keySeq).padStart(4, "0")}`;
}

function importInput(
  t: Tenant,
  rows: readonly Record<string, unknown>[],
  importKey = freshKey(),
  projectId: ProjectId = t.project.id,
) {
  return importIssuesSchema.parse({ orgId: t.org.id, projectId, importKey, rows });
}

async function projectIssueCount(t: Tenant, projectId = t.project.id) {
  return issueRepo.countIssues(t.org.id, projectId, { includeArchived: true });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("importer");
  other = await createTenant("elsewhere");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("importIssues", () => {
  it("creates every row, in file order, numbered after the project's highest number", async () => {
    const t = await createTenant("numbering");
    const first = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "Existing one" }),
    );
    await issueService.archiveIssue(t.actors.member, t.org.id, first.id);

    const result = await issueService.importIssues(
      t.actors.member,
      importInput(t, [
        {
          title: "Alpha row",
          description: "From the old tracker",
          status: "in_progress",
          priority: "high",
          dueAt: "2026-12-01T00:00:00.000Z",
        },
        { title: "Bravo row" },
        { title: "Charlie row", status: "done" },
      ]),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(t.project.id);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "Alpha row",
      "Bravo row",
      "Charlie row",
    ]);
    expect(result.issues.map((issue) => issue.number)).toEqual([2, 3, 4]);
    expect(result.issues[0]).toMatchObject({
      description: "From the old tracker",
      status: "in_progress",
      priority: "high",
      dueAt: "2026-12-01T00:00:00.000Z",
      authorId: t.userIds.member,
      assigneeId: null,
      parentId: null,
      estimate: null,
    });
    expect(result.issues[1]).toMatchObject({
      description: null,
      status: "backlog",
      priority: "none",
      dueAt: null,
    });

    const next = await issueService.createIssue(
      t.actors.member,
      issueInput(t.org.id, t.project.id, { title: "After the import" }),
    );
    expect(next.number).toBe(5);
  });

  it("assigns only current active members, matching the address case-insensitively", async () => {
    const t = await createTenant("assignees");
    const removed = await memberRepo.findMember(t.org.id, t.userIds.admin);
    await memberRepo.archiveMember(t.org.id, removed!.id);

    const result = await issueService.importIssues(
      t.actors.member,
      importInput(t, [
        { title: "Mixed case", assigneeEmail: "Viewer@Assignees.TEST" },
        { title: "Unknown", assigneeEmail: "nobody@assignees.test" },
        { title: "Other workspace", assigneeEmail: "member@elsewhere.test" },
        { title: "Removed member", assigneeEmail: "admin@assignees.test" },
        { title: "No one", assigneeEmail: null },
      ]),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      t.userIds.viewer,
      null,
      null,
      null,
      null,
    ]);
  });

  it("reuses existing labels, creates missing ones once and ignores other workspaces", async () => {
    const t = await createTenant("labels");
    const bug = await labelRepo.insertLabel({
      orgId: t.org.id,
      name: "bug",
      color: "#ff0000",
      description: "Existing",
    });
    await labelRepo.insertLabel({
      orgId: other.org.id,
      name: "infra",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      t.actors.member,
      importInput(t, [
        { title: "Two labels", labels: ["bug", "infra", "bug"] },
        { title: "Case differs", labels: ["Bug", "infra"] },
        { title: "No labels" },
      ]),
    );

    const orgLabels = await labelRepo.listLabels(t.org.id);
    expect(orgLabels.map((label) => label.name).sort()).toEqual(["Bug", "bug", "infra"]);
    const byName = new Map(orgLabels.map((label) => [label.name, label]));
    expect(byName.get("infra")).toMatchObject({ color: "#94a3b8", description: null });
    expect(byName.get("bug")).toMatchObject({ id: bug.id, color: "#ff0000" });

    expect(result.issues[0]?.labelIds).toEqual([bug.id, byName.get("infra")?.id]);
    expect(result.issues[1]?.labelIds).toEqual([
      byName.get("Bug")?.id,
      byName.get("infra")?.id,
    ]);
    expect(result.issues[2]?.labelIds).toEqual([]);

    const otherLabels = await labelRepo.listLabels(other.org.id);
    expect(otherLabels.map((label) => label.name)).toEqual(["infra"]);
  });

  it("replays a key the workspace already imported, creating nothing", async () => {
    const key = freshKey();
    const first = await issueService.importIssues(
      tenant.actors.member,
      importInput(tenant, [{ title: "Replay one" }, { title: "Replay two" }], key),
    );
    const before = await projectIssueCount(tenant);
    const imported = capture("issues.imported");

    const again = await issueService.importIssues(
      tenant.actors.admin,
      importInput(tenant, [{ title: "Something else entirely" }], key),
    );

    expect(again.replayed).toBe(true);
    expect(again.importKey).toBe(key);
    expect(again.issues).toEqual(first.issues);
    expect(await projectIssueCount(tenant)).toBe(before);
    expect(imported).toHaveLength(0);
  });

  it("treats a different key, or the same key in another workspace, as a new import", async () => {
    const key = freshKey();
    const rows = [{ title: "Same rows" }];
    const first = await issueService.importIssues(
      tenant.actors.member,
      importInput(tenant, rows, key),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      importInput(tenant, rows),
    );
    const elsewhere = await issueService.importIssues(
      other.actors.member,
      importInput(other, rows, key),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
    expect(elsewhere.replayed).toBe(false);
    expect(elsewhere.issues[0]?.orgId).toBe(other.org.id);
  });

  it("announces the batch once, with no per-issue events, notifications or webhooks", async () => {
    const t = await createTenant("announce");
    await webhookRepo.insertEndpoint(
      {
        orgId: t.org.id,
        url: "https://hooks.example.test/in",
        eventTypes: ["issue.created", "issue.assigned"],
      },
      "secret",
    );
    const imported = capture("issues.imported");
    const created = capture("issue.created");
    const assigned = capture("issue.assigned");
    const key = freshKey();

    const result = await issueService.importIssues(
      t.actors.member,
      importInput(
        t,
        [
          { title: "Quokka migration", assigneeEmail: "admin@announce.test" },
          { title: "Wombat migration" },
        ],
        key,
      ),
    );
    const ids = result.issues.map((issue) => issue.id);

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: t.org.id,
      actorId: t.userIds.member,
      projectId: t.project.id,
      importKey: key,
      issueIds: ids,
    });

    const hits = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "Quokka",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id)).toEqual([ids[0]]);

    const usage = await usageRepo.getUsage(t.org.id);
    expect(usage.issuesUsed).toBe(2);
    expect((await usageRepo.recomputeUsage(t.org.id)).issuesUsed).toBe(2);

    const audit = await activityRepo.listActivity({
      orgId: t.org.id,
      limit: 100,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: t.userIds.member,
      subjectKind: "project",
      subjectId: t.project.id,
      projectId: t.project.id,
      metadata: { count: 2, importKey: key },
    });

    const db = getDb();
    expect(
      db.select().from(notifications).where(eq(notifications.orgId, t.org.id)).all(),
    ).toHaveLength(0);
    expect(
      db
        .select()
        .from(webhookDeliveries)
        .where(eq(webhookDeliveries.orgId, t.org.id))
        .all(),
    ).toHaveLength(0);
  });
});

describe("importIssues refusals", () => {
  it("refuses a viewer, another workspace, an unknown or archived project", async () => {
    const rows = [{ title: "Never written", labels: ["refused"] }];

    await expect(
      issueService.importIssues(tenant.actors.viewer, importInput(tenant, rows)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      issueService.importIssues(tenant.actors.member, importInput(other, rows)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.importIssues(
        tenant.actors.member,
        importInput(tenant, rows, freshKey(), other.project.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await createTenant("archivedproj");
    await projectRepo.archiveProject(archived.org.id, archived.project.id);
    await expect(
      issueService.importIssues(archived.actors.member, importInput(archived, rows)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const refusedLabels = getDb()
      .select()
      .from(labels)
      .where(eq(labels.name, "refused"))
      .all();
