    expect(again.replayed).toBe(true);
    expect(again.importKey).toBe(key);
    expect(again.issues).toEqual(first.issues);
    expect(await projectIssueCount(tenant)).toBe(before);
    expect(imported).toHaveLength(0);
  });

  it("treats a different key, or the same key in another workspace, as a new import", async () => {
    const key = freshKey();
    const rows = [{ title: "Same rows" }];
    const first = await issueService.importIssues(
      tenant.actors.member,
      importInput(tenant, rows, key),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      importInput(tenant, rows),
    );
    const elsewhere = await issueService.importIssues(
      other.actors.member,
      importInput(other, rows, key),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
    expect(elsewhere.replayed).toBe(false);
    expect(elsewhere.issues[0]?.orgId).toBe(other.org.id);
  });

  it("announces the batch once, with no per-issue events, notifications or webhooks", async () => {
    const t = await createTenant("announce");
    await webhookRepo.insertEndpoint(
      {
        orgId: t.org.id,
        url: "https://hooks.example.test/in",
        eventTypes: ["issue.created", "issue.assigned"],
      },
      "secret",
    );
    const imported = capture("issues.imported");
    const created = capture("issue.created");
    const assigned = capture("issue.assigned");
    const key = freshKey();

    const result = await issueService.importIssues(
      t.actors.member,
      importInput(
        t,
        [
          { title: "Quokka migration", assigneeEmail: "admin@announce.test" },
          { title: "Wombat migration" },
        ],
        key,
      ),
    );
    const ids = result.issues.map((issue) => issue.id);

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: t.org.id,
      actorId: t.userIds.member,
      projectId: t.project.id,
      importKey: key,
      issueIds: ids,
    });

    const hits = await searchService.search(t.actors.member, {
      orgId: t.org.id,
      q: "Quokka",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.id)).toEqual([ids[0]]);

    const usage = await usageRepo.getUsage(t.org.id);
    expect(usage.issuesUsed).toBe(2);
    expect((await usageRepo.recomputeUsage(t.org.id)).issuesUsed).toBe(2);

    const audit = await activityRepo.listActivity({
      orgId: t.org.id,
      limit: 100,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: t.userIds.member,
      subjectKind: "project",
      subjectId: t.project.id,
      projectId: t.project.id,
      metadata: { count: 2, importKey: key },
    });

    const db = getDb();
    expect(
      db.select().from(notifications).where(eq(notifications.orgId, t.org.id)).all(),
    ).toHaveLength(0);
    expect(
      db
        .select()
        .from(webhookDeliveries)
        .where(eq(webhookDeliveries.orgId, t.org.id))
        .all(),
    ).toHaveLength(0);
  });
});

describe("importIssues refusals", () => {
  it("refuses a viewer, another workspace, an unknown or archived project", async () => {
    const rows = [{ title: "Never written", labels: ["refused"] }];

    await expect(
      issueService.importIssues(tenant.actors.viewer, importInput(tenant, rows)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      issueService.importIssues(tenant.actors.member, importInput(other, rows)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.importIssues(
        tenant.actors.member,
        importInput(tenant, rows, freshKey(), other.project.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    const archived = await createTenant("archivedproj");
    await projectRepo.archiveProject(archived.org.id, archived.project.id);
    await expect(
      issueService.importIssues(archived.actors.member, importInput(archived, rows)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const refusedLabels = getDb()
      .select()
      .from(labels)
      .where(eq(labels.name, "refused"))
      .all();
    expect(refusedLabels).toHaveLength(0);
  });

  it("refuses a batch that would take the project over its plan quota, keeping the key", async () => {
    const t = await createTenant("importquota", "free");
    for (let number = 1; number <= 98; number += 1) {
      await issueRepo.insertIssue(
        issueInput(t.org.id, t.project.id, { title: `Seed ${number}` }),
        t.userIds.member,
        number,
      );
    }
    const imported = capture("issues.imported");
    const key = freshKey();

    await expect(
      issueService.importIssues(
        t.actors.member,
        importInput(t, [{ title: "One", labels: ["quota"] }, { title: "Two" }, { title: "Three" }], key),
      ),
    ).rejects.toThrow(/allows no more issues/);
    expect(await projectIssueCount(t)).toBe(98);
    expect(await labelRepo.listLabels(t.org.id)).toHaveLength(0);
    expect(imported).toHaveLength(0);

    const retry = await issueService.importIssues(
      t.actors.member,
      importInput(t, [{ title: "One" }, { title: "Two" }], key),
    );
    expect(retry.replayed).toBe(false);
    expect(retry.issues.map((issue) => issue.number)).toEqual([99, 100]);
  });

  it("spends one unit of the issue-creation allowance per row and refuses when it runs out", async () => {
    const t = await createTenant("importrate");
    const capacity = getBucketConfig("issue:create").capacity;

    await issueService.importIssues(
      t.actors.member,
      importInput(t, [{ title: "Spend one" }, { title: "Spend two" }]),
    );
    const left = await consumeRateLimit(t.org.id, "issue:create", 0);
    expect(left.remaining).toBe(capacity - 2);

    await consumeRateLimit(t.org.id, "issue:create", capacity - 3);
    const key = freshKey();
    await expect(
      issueService.importIssues(
        t.actors.member,
        importInput(t, [{ title: "Over" }, { title: "The" }, { title: "Limit" }], key),
      ),
    ).rejects.toThrow(/rate limit/);
    expect(await projectIssueCount(t)).toBe(2);
  });
});

