/**
 * Bulk import from another tracker. Gated exactly like `createIssue`, then
 * all or nothing: a key this workspace has already imported replays the first
 * result; otherwise the whole batch must fit the project's quota and the
 * workspace's issue-creation allowance before a single row is written. The
 * batch is announced once, as `issues.imported` — never as per-issue
 * `issue.created` — so nobody is notified and no webhook fires for it.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const previous = await importRepo.findImport(input.orgId, input.importKey);
  if (previous) return replayImport(previous);

  await assertProjectHasRoom(project, input.rows.length);

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assignees = new Map(
    (await memberRepo.listActiveMemberEmails(input.orgId)).map((member) => [
      member.email.toLowerCase(),
      member.userId,
    ]),
  );

  const record = await importRepo.insertImport({
    orgId: input.orgId,
    projectId: project.id,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => toImportDraft(row, assignees)),
    newLabelColor: DEFAULT_LABEL_COLOR,
  });

  // A concurrent upload of the same key got its write in first.
  if (record === null) {
    return replayImport(
      requireFound(
        await importRepo.findImport(input.orgId, input.importKey),
        "Import",
        input.importKey,
      ),
    );
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: record.projectId,
    importKey: record.importKey,
    issueIds: record.issueIds,
  });

  return {
    importKey: record.importKey,
    projectId: record.projectId,
    issues: await issueRepo.findIssuesByIds(record.orgId, record.issueIds),
    replayed: false,
  };
}

